import React, { useRef, useState, useEffect } from "react";
import { Input, Button, List, Avatar, message as antdMsg } from "antd";
import { UserOutlined, RobotOutlined } from "@ant-design/icons";
import axios from "axios";

const API_URL = "http://localhost:8000/rag/chat";

function ChatBox() {
  const [input, setInput] = useState("");
  const [chatList, setChatList] = useState([]);
  const [loading, setLoading] = useState(false);
  const [sessionId, setSessionId] = useState(() => localStorage.getItem("session_id") || "");
  const listRef = useRef(null);

  useEffect(() => {
    if (listRef.current) {
      listRef.current.scrollTop = listRef.current.scrollHeight;
    }
  }, [chatList]);

  const sendMsg = async () => {
    if (!input.trim()) return;
    setLoading(true);
    const userMsg = { role: "user", content: input };
    setChatList((prev) => [...prev, userMsg]);
    try {
      const resp = await axios.post(API_URL, {
        question: input,
        session_id: sessionId || undefined
      });
      setSessionId(resp.data.session_id);
      localStorage.setItem("session_id", resp.data.session_id);
      setChatList((prev) => [
        ...prev,
        { role: "assistant", content: resp.data.answer }
      ]);
      setInput("");
    } catch (e) {
      antdMsg.error("请求失败");
    }
    setLoading(false);
  };

  const handleInputKeyDown = (e) => {
    if (e.key === "Enter" && !loading) {
      sendMsg();
    }
  };

  return (
    <div style={{
      position: "relative", minHeight: 500, background: "#fff",
      borderRadius: 16, boxShadow: "0 2px 16px rgba(0,0,0,0.06)",
      paddingBottom: 80, marginBottom: 24
    }}>
      <div
        ref={listRef}
        style={{
          maxHeight: 500, overflowY: "auto", padding: 24, paddingBottom: 0
        }}
      >
        <List
          dataSource={chatList}
          renderItem={(item, idx) => (
            <List.Item
              style={{
                border: "none", padding: 0, marginBottom: 16,
                justifyContent: item.role === "user" ? "flex-end" : "flex-start"
              }}
            >
              {item.role === "assistant" && (
                <Avatar
                  icon={<RobotOutlined />}
                  style={{ background: "#409eff", marginRight: 8 }}
                />
              )}
              <div
                style={{
                  background: item.role === "user" ? "#e6f7ff" : "#f5f5f5",
                  color: "#222", borderRadius: 16, padding: "10px 18px",
                  maxWidth: 420, wordBreak: "break-all", fontSize: 16
                }}
              >
                {item.content}
              </div>
              {item.role === "user" && (
                <Avatar
                  icon={<UserOutlined />}
                  style={{ background: "#87d068", marginLeft: 8 }}
                />
              )}
            </List.Item>
          )}
        />
      </div>
      <div
        style={{
          position: "absolute", left: 0, right: 0, bottom: 0,
          padding: 16, background: "#fff", borderRadius: "0 0 16px 16px",
          boxShadow: "0 -2px 8px rgba(0,0,0,0.03)"
        }}
      >
        <Input
          size="large"
          placeholder="请输入您的问题…"
          value={input}
          onChange={e => setInput(e.target.value)}
          onKeyDown={handleInputKeyDown}
          style={{ width: "calc(100% - 100px)", marginRight: 12, borderRadius: 24 }}
          disabled={loading}
        />
        <Button
          type="primary"
          size="large"
          style={{ borderRadius: 24, width: 80 }}
          onClick={sendMsg}
          loading={loading}
        >
          发送
        </Button>
      </div>
    </div>
  );
}

export default ChatBox;
